const std = @import("std");
const C = @import("canvas.zig");
const Crossing = struct { start: i64, direction: i64 };
fn less(_: void, a: Crossing, b: Crossing) bool { return if (a.start == b.start) a.direction < b.direction else a.start < b.start; }
fn crossingStart(a: C.Point, b: C.Point, y: i64) i64 { var denominator = b.y - a.y; var numerator = 2 * a.x * denominator + (2 * y + 1 - 2 * a.y) * (b.x - a.x); if (denominator < 0) { numerator = -numerator; denominator = -denominator; } return @divFloor(numerator - denominator, 2 * denominator) + 1; }
pub fn polygons(mask: C.Mask, sequences: []const []const C.Point, rule: C.Rule, clip: C.Rect) void { var edges: std.ArrayList(C.Segment) = .empty; for (sequences) |vertices| { for (vertices, 0..) |first, i| { const last = vertices[(i + 1) % vertices.len]; if (first.y != last.y) C.push(C.Segment, &edges, .{ .first = first, .last = last }); } } var y = clip.y0;
    while (y <= clip.y1) : (y += 1) { var crossings: std.ArrayList(Crossing) = .empty; for (edges.items) |edge| { if (@min(edge.first.y, edge.last.y) <= y and y < @max(edge.first.y, edge.last.y)) C.push(Crossing, &crossings, .{ .start = crossingStart(edge.first, edge.last, y), .direction = if (edge.last.y > edge.first.y) 1 else -1 }); } std.mem.sort(Crossing, crossings.items, {}, less); var count: usize = 0; var winding: i64 = 0; var index: usize = 0; var x = clip.x0;
        while (x <= clip.x1) : (x += 1) { while (index < crossings.items.len and crossings.items[index].start <= x) : (index += 1) { count += 1; winding += crossings.items[index].direction; } if (if (rule == .evenodd) count % 2 == 1 else winding != 0) mask.add(.{ .x = x, .y = y }, clip); }
    }
}
pub fn shape(mask: C.Mask, center: C.Point, points: []const C.Point, clip: C.Rect) void { var extents = [_]i64{-1} ** 201; for (points) |point| { const i = C.index(point.y + 100); extents[i] = @max(extents[i], C.abs(point.x)); } for (extents, 0..) |extent, i| { if (extent < 0) continue; const y = center.y + C.int(i) - 100; if (y < clip.y0 or y > clip.y1) continue; var x = @max(clip.x0, center.x - extent); const end = @min(clip.x1, center.x + extent); while (x <= end) : (x += 1) mask.add(.{ .x = x, .y = y }, clip); } }
fn sameColor(a: ?C.Color, b: ?C.Color) bool { if (a == null or b == null) return a == null and b == null; return std.mem.eql(i64, &a.?, &b.?); }
pub fn flood(mask: C.Mask, layer: *const C.Layer, seed: C.Point, clip: C.Rect) void { const target = layer.colors[C.index(seed.y) * mask.width + C.index(seed.x)]; var pending: std.ArrayList(C.Point) = .empty; mask.add(seed, clip); C.push(C.Point, &pending, seed); while (pending.pop()) |point| { const neighbors = [_]C.Point{ .{ .x = point.x + 1, .y = point.y }, .{ .x = point.x - 1, .y = point.y }, .{ .x = point.x, .y = point.y + 1 }, .{ .x = point.x, .y = point.y - 1 } }; for (neighbors) |next| { if (!clip.contains(next)) continue; const pixel = C.index(next.y) * mask.width + C.index(next.x); if (!mask.bits[pixel] and sameColor(layer.colors[pixel], target)) { mask.bits[pixel] = true; C.push(C.Point, &pending, next); } } } }
